new_fn="async function earthlineFetchOverpass15862P(result,boundary,myGen){\n  /* M191: retrieve the small Property frame directly from OSM's read-only\n     map endpoint. Overpass rate-limits the POST; zero data is NOT clear.\n     A source response with mapped geometry alone allows SCREENING,\n     never authoritative clearance. No new prescribed geometry. */\n  result.overpass.attempted=true;\n  result.overpass.ok=false;result.overpass.error=null;\n  result.overpass.provider='openstreetmap-api-0.6-map';\n  const lngs=boundary.map(p=>Number(p[0])),lats=boundary.map(p=>Number(p[1]));\n  const lat0=lats.reduce((a,b)=>a+b,0)/lats.length;\n  const latPad=30/111320,lngPad=30/(111320*Math.max(.05,Math.cos(lat0*Math.PI/180)));\n  const south=Math.min(...lats)-latPad,north=Math.max(...lats)+latPad;\n  const west=Math.min(...lngs)-lngPad,east=Math.max(...lngs)+lngPad;\n  const span=(north-south)*(east-west);\n  if(!(span>0&&span<=0.00014)){\n    result.overpass.error='property-frame-outside-safe-openstreetmap-query-area';return false;\n  }\n  const bbox=[west,south,east,north].map(v=>v.toFixed(7)).join(',');\n  const controller=typeof AbortController!=='undefined'?new AbortController():null;\n  const timer=controller?setTimeout(()=>controller.abort(),9500):null;\n  try{\n    const response=await fetch('https://api.openstreetmap.org/api/0.6/map?bbox='+encodeURIComponent(bbox),{\n      method:'GET',signal:controller?.signal,mode:'cors'});\n    result.overpass.httpStatus=response.status;\n    result.overpass.queryBBox=bbox;\n    if(!response.ok)throw new Error('OSM HTTP '+response.status);\n    const raw=await response.text();\n    result.overpass.responseBytes=new TextEncoder().encode(raw).length;\n    const xml=new DOMParser().parseFromString(raw,'application/xml');\n    if(xml.getElementsByTagName('parsererror').length)throw new Error('OSM invalid XML');\n    if(xml.documentElement?.localName!=='osm')throw new Error('OSM wrong XML root');\n    const bounds=xml.getElementsByTagName('bounds');\n    if(bounds.length!==1)throw new Error('OSM missing authoritative BBOX');\n    const b=bounds[0],num=k=>Number(b.getAttribute(k));\n    const eps=0.00001;\n    if(!['minlon','minlat','maxlon','maxlat'].every(k=>b.hasAttribute(k)&&Number.isFinite(num(k)))||\n       num('minlon')>west+eps||num('minlat')>south+eps||\n       num('maxlon')<east-eps||num('maxlat')<north-eps)\n      throw new Error('OSM response BBOX incomplete');\n    if(earthlineIsStale(myGen))return false;\n    const nodes=new Map();\n    for(const node of xml.getElementsByTagName('node')){\n      const lon=Number(node.getAttribute('lon')),lat=Number(node.getAttribute('lat'));\n      if(Number.isFinite(lon)&&Number.isFinite(lat))\n        nodes.set(node.getAttribute('id'),{lon,lat});\n    }\n    const ways=new Map();\n    let usable=0;\n    for(const w of xml.getElementsByTagName('way')){\n      const tags={};\n      for(const tag of w.getElementsByTagName('tag'))tags[tag.getAttribute('k')]=tag.getAttribute('v');\n      const geometry=Array.from(w.getElementsByTagName('nd')).map(nd=>nodes.get(nd.getAttribute('ref'))).filter(Boolean);\n      const item={id:w.getAttribute('id'),tags,geometry};\n      ways.set(item.id,item);\n      if(geometry.length>1)usable+=earthlineRasterOverpassElement15862P(result,item);\n    }\n    for(const rel of xml.getElementsByTagName('relation')){\n      const tags={};\n      for(const tag of rel.getElementsByTagName('tag'))tags[tag.getAttribute('k')]=tag.getAttribute('v');\n      const members=Array.from(rel.getElementsByTagName('member')).filter(x=>x.getAttribute('type')==='way')\n        .map(x=>({role:x.getAttribute('role'),geometry:ways.get(x.getAttribute('ref'))?.geometry||[]}));\n      if(members.some(x=>x.geometry.length>1))\n        usable+=earthlineRasterOverpassElement15862P(result,{tags,members});\n    }\n    result.overpass.rawElementCount=ways.size+xml.getElementsByTagName('relation').length;\n    result.overpass.sourceComplete=true;\n    result.processedGeometryCount+=usable;\n    result.overpass.ok=true;\n    return usable>0;\n  }catch(error){\n    result.overpass.error=String(error?.message||error);\n    return false;\n  }finally{if(timer)clearTimeout(timer)}\n}\n  "
new_gate="if(openDataResponded&&op.provider==='openstreetmap-api-0.6-map'&&op.sourceComplete===true&&\n       Number(op.httpStatus)===200&&!op.error&&openGeometryCount16516===0){\n      c.sourceTier=\"open-data\";c.acquisitionResult=\"screened-clear\";\n      c.publicationAllowed=true;c.exclusionVerified=false;\n      c.evidenceGrade=\"NO MAPPED ROADS, BUILDINGS OR WATER FOUND · FIELD VERIFICATION REQUIRED\";\n      c.openGeometryCount16516=0;\n      c.openDataSources16539={overpass:{attempted:true,responded:true,failed:false,sourceComplete:true},style:{attempted:styleAttempted,responded:styleResponded,failed:styleFailed}};\n      earthlineSetVectorVerification16343(c,\"unverified\",\"complete-osm-zero-mapped-exclusions-screening-only\");\n      return true;\n    }\n    if(openDataResponded){\n      /* M175: an empty non-authoritative map-source response cannot certify road,\n         building or narrow-channel clearance. Fail closed until independent\n         mapped exclusion evidence is available; never treat blank as clear. */\n      c.sourceTier=\"open-data\";c.acquisitionResult=\"failed\";c.publicationAllowed=false;c.exclusionVerified=false;\n      c.evidenceGrade=\"ROAD AND WATER CHECK UNAVAILABLE · TRY AGAIN\";\n      c.openGeometryCount16516=0;\n      c.openDataSources16539={overpass:{attempted:!!op.attempted,responded:overpassResponded,failed:overpassFailed},style:{attempted:styleAttempted,responded:styleResponded,failed:styleFailed}};\n      earthlineSetVectorVerification16343(c,\"unverified\",\"empty-open-data-does-not-establish-road-or-water-clearance\");\n      return false;\n    }\n    "
